// ------------------------------------------------------------------ UI 语言
/** v1.7.53：dsh-mall 自身的 UI 语言（独立于宿主全局语言，随商场语言按钮切换）。 */
export type StoreUiLang = 'zh' | 'en' | 'ja' | 'ko' | 'es' | 'fr' | 'de' | 'pt' | 'ru' | 'ja' | 'ko' | 'es' | 'fr' | 'de' | 'pt' | 'ru' | 'ja' | 'ko' | 'es' | 'fr' | 'de' | 'pt' | 'ru'

let uiLang: StoreUiLang | null = null
const langListeners = new Set<() => void>()

export const storeLang = {
  init(l: StoreUiLang): void {
    if (uiLang !== null) return
    try {
      const saved = localStorage.getItem('dsh-mall-uilang')
      uiLang = (['zh', 'en', 'ja', 'ko', 'es', 'fr', 'de', 'pt', 'ru'] as const).includes(saved as StoreUiLang) ? (saved as StoreUiLang) : l
    } catch { uiLang = l }
  },
  get(): StoreUiLang {
    return uiLang ?? 'zh'
  },
  set(l: StoreUiLang): void {
    if (uiLang === l) return
    uiLang = l
    try { localStorage.setItem('dsh-mall-uilang', l) } catch { /* 忽略 */ }
    for (const fn of langListeners) fn()
  },
  subscribe(fn: () => void): () => void {
    langListeners.add(fn)
    return () => { langListeners.delete(fn) }
  },
}

/** 按当前商场 UI 语言取词条（缺 zh/en 兜底原 key）。 */
export function storeT(key: string): string {
  const dict = (storeLang.get() === 'zh' ? zh : storeLang.get() === 'ja' ? ja : storeLang.get() === 'ko' ? ko : storeLang.get() === 'es' ? es : storeLang.get() === 'fr' ? fr : storeLang.get() === 'de' ? de : storeLang.get() === 'pt' ? pt : storeLang.get() === 'ru' ? ru : en)
  return dict[key] ?? en[key] ?? key
}
